package transport

import ("bufio";"bytes";"context";"encoding/json";"io";"net/http";"strconv";"strings")
type Result struct{StatusCode int; Headers http.Header; Body []byte}
func DoJSON(ctx context.Context,c *http.Client,m,u string,h map[string]string,p any)(Result,error){var b io.Reader;if p!=nil{d,e:=json.Marshal(p);if e!=nil{return Result{},e};b=bytes.NewReader(d)};q,e:=http.NewRequestWithContext(ctx,m,u,b);if e!=nil{return Result{},e};q.Header.Set("Accept","application/json");if p!=nil{q.Header.Set("Content-Type","application/json")};for k,v:=range h{q.Header.Set(k,v)};r,e:=c.Do(q);if e!=nil{return Result{},e};defer r.Body.Close();d,e:=io.ReadAll(r.Body);if e!=nil{return Result{},e};return Result{r.StatusCode,r.Header.Clone(),d},nil}
func OpenSSE(ctx context.Context,c *http.Client,m,u string,h map[string]string,p any)(*http.Response,error){d,e:=json.Marshal(p);if e!=nil{return nil,e};q,e:=http.NewRequestWithContext(ctx,m,u,bytes.NewReader(d));if e!=nil{return nil,e};q.Header.Set("Accept","text/event-stream");q.Header.Set("Content-Type","application/json");for k,v:=range h{q.Header.Set(k,v)};return c.Do(q)}
func ReadSSE(ctx context.Context,r *http.Response,handle func(string)error)error{defer r.Body.Close();s:=bufio.NewScanner(r.Body);s.Buffer(make([]byte,64*1024),4*1024*1024);var b strings.Builder;flush:=func()error{if b.Len()==0{return nil};v:=strings.TrimSuffix(b.String(),"\n");b.Reset();return handle(v)};for s.Scan(){select{case<-ctx.Done():return ctx.Err();default:};l:=s.Text();if l==""{if e:=flush();e!=nil{return e};continue};if strings.HasPrefix(l,"data:"){if b.Len()>0{b.WriteByte('\n')};b.WriteString(strings.TrimSpace(strings.TrimPrefix(l,"data:")))}};if e:=s.Err();e!=nil{return e};return flush()}
func RetryAfter(h http.Header)int{n,_:=strconv.Atoi(strings.TrimSpace(h.Get("Retry-After")));return n}
